D0260    DC    HL2'0'              RETURN-CODE PIC S9(4)v0 COMP
D0261    DC    HL2'0'              SORT-RETURN PIC S9(4)v0 COMP
D0262    DC    FL4'0'              SORT-FILE-SIZE PIC S9(8)v0 COMP
LS0000   DSECT                     EXEC-PARAMETER (caller's storage)
D0253    DS    0CL11               EXEC-PARAMETER (01 group)
D0254    DS    CL2                 EXEC-PARAM-LENGTH
D0255    DS    CL1                 EXEC-PARAM-RESEQ
D0256    DS    CL8                 EXEC-PARAM-PROGNAME
*---------------------------------------------------------------
* COBRT -- our runtime. Nothing here is from SYS1.COBLIB.
* DISPLAY reaches SYSOUT through QSAM directly, which is the
* same access-method path IKFCBL00 uses for its own file I/O.
* Not reentrant: MVS 3.8j batch does not require it.
*---------------------------------------------------------------
COBRT    CSECT
         ENTRY COBDISP,COBTERM,COBWRL,COBDATE,COBACC,COBUPSI
         ENTRY COBADV,COBSTR,COBUNS,COBWTO,COBWTOR,COBADT,COBMVL
         ENTRY COBDCAL,COBCANC
*
* COBDISP -- write one line to SYSOUT.
*   R1 -> A(text), A(halfword length).  Opens SYSOUT on demand.
*
COBDISP  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE1+4
         LA    11,RTSAVE1
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(text)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)            length
         CLI   RTOPEN,X'01'        already open?
         BE    COBD010
         OPEN  (RTDCB,OUTPUT)
         MVI   RTOPEN,X'01'
COBD010  MVI   RTLINE,C' '         ASA: single space
         MVC   RTLINE+1(120),RTLINE  blank the text area
         LTR   4,4
         BNP   COBD020             empty: emit a blank line
         CH    4,RTMAX
         BNH   COBD015
         LH    4,RTMAX             truncate at line width
COBD015  BCTR  4,0                 EX wants length-1
         EX    4,COBDMVC
COBD020  PUT   RTDCB,RTLINE
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
COBDMVC  MVC   RTLINE+1(0),0(2)    executed, never fallen into
*
* COBADV -- write one line of a print file, IBM's way.
*
*   R1 -> A(dcb), A(what PUT is given: the record, or its RDW),
*         A(the record), A(halfword owed), A(halfword request),
*         A(LINAGE cells) or 0, A(LINAGE-COUNTER) or 0
*
* The control character is the record's own first byte, a
* machine code, exactly as IKFCBL00 writes it (RECFM=FM):
* AFTER n is immediate spacing records -- 3 lines at a time,
* X'1B', then X'13' or X'0B' -- and the line with X'01',
* write without spacing; AFTER 0 is the no-op X'03' first.
* BEFORE n is the line with write-and-space, X'09' X'11'
* X'19', and immediate spacing for any more than three.
* A channel is skip-immediate (X'8B' for 1) after, or
* write-and-skip (X'89') before. Measured on TK5.
*
* The request is the line count, 999 for PAGE, 1001-1012 a
* channel, 1013 CSP, negated when the phrase was BEFORE.
* A LINAGE file keeps its own accounting, in which BEFORE's
* count is held over to the next line; the lines it arrives
* at are written the same way, AFTER-fashion.
COBADV   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE7+4
         LA    11,RTSAVE7
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(dcb)
         L     3,4(0,1)            A(what PUT writes)
         L     4,8(0,1)            A(the record): its first byte is the
         L     5,12(0,1)           A(owed)
         L     6,16(0,1)           A(request)
         L     10,20(0,1)          A(LINAGE cells), or 0
         L     11,24(0,1)          A(LINAGE-COUNTER), or 0
         LH    8,0(0,6)            the request
         LTR   10,10               a LINAGE file?
         BNZ   ADV400
         SR    7,7                 R7: END-OF-PAGE, never, without LINA
         LTR   8,8
         BM    ADV100              BEFORE
         CH    8,ADVCSP
         BE    ADV020              CSP: no spacing
         CH    8,ADVPAGE
         BL    ADV010
         BAL   14,ADVSKIPI         AFTER a channel: skip first
         B     ADV030
ADV010   LTR   9,8                 AFTER n lines
         BZ    ADV020
         BAL   14,ADVSPI           the spacing, immediate
         B     ADV030
ADV020   MVI   0(4),X'03'          AFTER 0: a no-op first
         PUT   (2),(3)
ADV030   MVI   0(4),X'01'          then write, no spacing
         PUT   (2),(3)             the line itself
         B     ADV900
ADV100   LCR   8,8                 BEFORE: a positive request
         CH    8,ADVCSP
         BE    ADV120              CSP: write without spacing
         CH    8,ADVPAGE
         BL    ADV110
         LA    9,ADVSKIPW          BEFORE a channel: write and skip
         BAL   14,ADVCHAN
         PUT   (2),(3)
         B     ADV900
ADV110   LTR   9,8
         BNZ   ADV130
ADV120   MVI   0(4),X'01'          BEFORE 0: write, no spacing
         PUT   (2),(3)
         B     ADV900
ADV130   CH    9,ADVTHREE          the line carries up to three
         BNH   ADV140
         LH    9,ADVTHREE
ADV140   IC    0,ADVWSP(9)         write and space 1, 2 or 3
         STC   0,0(0,4)
         PUT   (2),(3)             the line itself
         SR    8,9                 what is left beyond three
         LTR   9,8
         BZ    ADV900
         BAL   14,ADVSPI           the rest, immediate
         B     ADV900
ADV400   LH    9,0(0,5)            what the last BEFORE left owing
         LTR   8,8                 BEFORE is the negative side
         BM    ADV500
         CH    8,ADVPAGE           AFTER PAGE, or a channel?
         BNL   ADV420
         CH    9,ADVPAGE           was a skip already owed?
         BNL   ADV430              then it stays one, whatever this ask
         AR    9,8                 owed plus this one
         B     ADV430
ADV420   LR    9,8                 a skip swallows what was owed
ADV430   XC    0(2,5),0(5)         nothing owed after an AFTER
         B     ADV550
ADV500   LCR   8,8                 back to a positive request
         STH   8,0(0,5)            this is what the next line owes
         LTR   9,9                 nothing owed?
         BNZ   ADV550
         LH    9,ADVONE            then this line simply takes the next
ADV550   SR    7,7                 no END-OF-PAGE yet
         CH    9,ADVPAGE           a skip?
         BNL   ADV560
         LH    14,0(0,11)          LINAGE-COUNTER
         AR    14,9
         CH    14,0(0,10)          past the body?
         BH    ADV560
         STH   14,0(0,11)
         LH    0,2(0,10)           FOOTING
         LTR   0,0
         BZ    ADV600              no FOOTING: no END-OF-PAGE short of
         CR    14,0
         BL    ADV600
         LA    7,1                 END-OF-PAGE
         B     ADV600
ADV560   LH    14,ADVONE
         STH   14,0(0,11)          counter back to 1
         LA    7,1                 a new page is END-OF-PAGE without FO
         LH    0,2(0,10)
         LTR   0,0
         BZ    ADV570
         SR    7,7                 with FOOTING, only the footing is
ADV570   LH    8,ADVPAGE           a new page
         BAL   14,ADVSKIPI         skip to it now
         LH    9,4(0,10)           then LINES AT TOP
ADV600   CH    9,ADVPAGE
         BL    ADV610
         LR    8,9
         BAL   14,ADVSKIPI         a page or a channel, immediate
         B     ADV620
ADV610   LTR   9,9
         BNP   ADV620
         BAL   14,ADVSPI           the spacing, immediate
ADV620   MVI   0(4),X'01'          the line: write, no spacing
         PUT   (2),(3)
ADV900   L     13,4(13)
         ST    7,16(13)            END-OF-PAGE, into R15's slot for the
         LM    14,12,12(13)
         BR    14
ADVSPI   ST    14,ADVR14
ADVSP1   CH    9,ADVTHREE
         BNH   ADVSP2
         MVI   0(4),X'1B'          space 3 lines, immediate
         PUT   (2),(3)
         SH    9,ADVTHREE
         B     ADVSP1
ADVSP2   IC    0,ADVISP(9)         space 1, 2 or 3, immediate
         STC   0,0(0,4)
         PUT   (2),(3)
         L     14,ADVR14
         BR    14
ADVSKIPI ST    14,ADVR14
         LA    9,ADVSKIP
         BAL   14,ADVCHAN
         PUT   (2),(3)
         L     14,ADVR14
         BR    14
ADVCHAN  LR    0,8
         CH    0,ADVPAGE
         BNE   ADVCH1
         LH    0,ADVCHOF           PAGE is channel 1
ADVCH1   SH    0,ADVCHOF           0 for channel 1
         AR    9,0
         MVC   0(1,4),0(9)
         BR    14
ADVSKIP  DC    X'8B939BA3ABB3BBC3CBD3DBE3'  skip to channel 1-12, immed
ADVSKIPW DC    X'899199A1A9B1B9C1C9D1D9E1'  write, then skip to channel
ADVWSP   DC    X'01091119'         write, then space 0-3
ADVISP   DC    X'030B131B'         space 0-3, immediate
ADVCHOF  DC    H'1001'
ADVCSP   DC    H'1013'
ADVONE   DC    H'1'
ADVPAGE  DC    H'999'              the page-skip request
ADVTHREE DC    H'3'
ADVR14   DS    F
RTSAVE7  DS    18F
*
* COBUPSI -- set the eight switches from the EXEC PARM.
*
* PARM='/UPSI(10100000)' is the form IBM's later compilers
* take, and the one the runtime looks for: the literal UPSI
* anywhere in the parameter text, then the next eight 0 or 1
* characters, leftmost being UPSI-0. Anything else leaves all
* eight off, which is the documented default.
COBUPSI  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE6+4
         LA    11,RTSAVE6
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(parameter text)
         LA    2,0(0,2)            drop the end-of-list bit
         XC    RTUPSI,RTUPSI       all off unless the PARM says otherwi
         LH    3,0(0,2)            its length
         LA    4,2(0,2)            the text itself
         CH    3,UPSIMIN           room for UPSI and eight digits?
         BL    UPSX
         SH    3,UPSIMIN
         LA    3,1(3)              positions worth trying
UPS10    CLC   0(4,4),UPSITAG
         BE    UPS15
         LA    4,1(4)
         BCT   3,UPS10
         B     UPSX                no UPSI in the parameter
UPS15    LA    4,4(4)              past the tag
         CLI   0(4),C'0'
         BE    UPS20
         CLI   0(4),C'1'
         BE    UPS20
         LA    4,1(4)              skip a ( or an =
UPS20    SR    5,5                 the byte being built
         LA    6,8                 eight of them
UPS30    SLL   5,1
         CLI   0(4),C'1'
         BNE   UPS40
         LA    5,1(5)
UPS40    LA    4,1(4)
         BCT   6,UPS30
         ST    5,RTUPSI            the byte, for the caller to store
UPSX     L     13,4(13)
         L     15,RTUPSI           the byte, while R12 is still ours
         ST    15,16(13)           into the save area's R15 slot
         LM    14,12,12(13)
         BR    14
*
* COBACC -- one transfer from SYSIN into the caller's item.
*
* General rule 2 on II-53 leaves the size of a transfer to the
* implementor: here it is one 80-column record. The buffer is
* blanked first, so a receiver wider than a card is padded and
* a read past the last card returns spaces rather than the
* card before it.
*
* Parameter list: A(item), A(halfword length).
COBACC   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE5+4
         LA    11,RTSAVE5
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(item)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)            length still to fill
COBA005  LTR   4,4
         BNP   COBA040             filled
         MVI   ACCBUF,C' '
         MVC   ACCBUF+1(255),ACCBUF  blank the buffer
         CLI   ACCEOFF,X'01'       already at end of file?
         BE    COBA020
         CLI   ACCOPEN,X'01'       already open?
         BE    COBA010
         OPEN  (ACCDCB,INPUT)
         MVI   ACCOPEN,X'01'
COBA010  LA    1,COBA030
         STCM  1,7,ACCDCB+33       into DCBEODAD
         GET   ACCDCB,ACCBUF       one card
         B     COBA020
COBA030  MVI   ACCEOFF,X'01'       end of file: the buffer stays blank
COBA020  LR    5,4
         CH    5,ACCCARD
         BNH   COBA035
         LH    5,ACCCARD           one card's worth
COBA035  BCTR  5,0                 EX wants length-1
         EX    5,COBAMVC
         LA    2,1(5,2)            past what was stored
         LA    5,1(5)
         SR    4,5
         B     COBA005
COBA040  L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
COBAMVC  MVC   0(0,2),ACCBUF       patched by EX
ACCCARD  DC    H'80'               a card
*
* COBTERM -- close SYSOUT if COBDISP ever opened it.
*
COBTERM  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE2+4
         LA    11,RTSAVE2
         ST    11,8(13)
         LR    13,11
         CLI   ACCOPEN,X'01'
         BNE   COBT005
         CLOSE (ACCDCB)
         MVI   ACCOPEN,X'00'
COBT005  CLI   RTOPEN,X'01'
         BNE   COBT010
         CLOSE (RTDCB)
         MVI   RTOPEN,X'00'
COBT010  L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
*
* COBDATE -- fill an 8-byte field with MM/DD/YY.
*   R1 -> the field.  TIME DEC hands back the date as packed
*   00YYDDDF, which is Julian, so the day of year has to be
*   walked into a month and a day.
*
COBDATE  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE4+4
         LA    11,RTSAVE4
         ST    11,8(13)
         LR    13,11
         LR    2,1                 the field, before TIME takes R1
         TIME  DEC                 R0 = HHMMSSth, R1 = 00YYDDDF
         ST    1,DTPACK
         UNPK  DTZONE(7),DTPACK(4)  '00YYDDD'
         OI    DTZONE+6,X'F0'
         PACK  DTDW(8),DTZONE+4(3)
         CVB   3,DTDW              day of the year
         PACK  DTDW(8),DTZONE+2(2)
         CVB   4,DTDW              the year
         N     4,DTF3              zero if a leap year -- 1901-2099, so
*                             mod 4 is the whole rule
         LA    5,1                 month
         LA    6,DTMON
DT010    SR    7,7
         IC    7,0(0,6)            days in this month
         CH    5,DTH2              February?
         BNE   DT020
         LTR   4,4
         BNZ   DT020
         LA    7,1(0,7)            29 this year
DT020    CR    3,7
         BNH   DT030               the day falls in this month
         SR    3,7
         LA    5,1(0,5)
         LA    6,1(0,6)
         B     DT010
DT030    CVD   5,DTDW
         UNPK  0(2,2),DTDW+6(2)    MM
         OI    1(2),X'F0'
         MVI   2(2),C'/'
         CVD   3,DTDW
         UNPK  3(2,2),DTDW+6(2)    DD
         OI    4(2),X'F0'
         MVI   5(2),C'/'
         MVC   6(2,2),DTZONE+2     YY, already zoned
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
DTMON    DC    AL1(31,28,31,30,31,30,31,31,30,31,30,31)
DTF3     DC    F'3'
DTH2     DC    H'2'
DTPACK   DS    F
DTZONE   DS    CL8
DTDW     DS    D
RTSAVE4  DS    18F
*
* COBWRL -- position the paper and write one report line.
*   R1 -> A(dcb), A(physical line), A(target line), A(buffer),
*         A(pending carriage control), A(LINE-COUNTER)
* The physical line is where the paper is; LINE-COUNTER is the
* standard's register, which NEXT GROUP moves without moving
* paper. Both end at the line printed. A pending eject rides on
* the line itself when the target is line 1; otherwise a blank
* line ejects first, so the spacing blanks land on the new page.
*
COBWRL   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE3+4
         LA    11,RTSAVE3
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(dcb)
         L     3,4(0,1)            A(physical line)
         L     4,8(0,1)            A(target line)
         L     5,12(0,1)           A(buffer)
         L     9,16(0,1)           A(pending control)
         L     10,20(0,1)          A(LINE-COUNTER)
         L     11,24(0,1)          A(this report's blank line)
         L     6,0(0,3)            the physical line
         L     7,0(0,4)            the target
         MVI   0(5),C' '           single space unless told otherwise
         CLI   0(9),C'1'           an eject pending?
         BNE   COBW010
         MVI   0(9),C' '           once
         CH    7,RWONE             to line 1?
         BNE   COBW005
         MVI   0(5),C'1'           the line itself ejects
         SR    6,6
         B     COBW020
COBW005  MVI   0(11),C'1'          the blank line ejects
         PUT   (2),(11)            a blank line at the top of a new pag
         MVI   0(11),C' '
         LA    6,1
COBW010  CR    7,6                 a target behind the paper?
         BH    COBW012
         LA    7,1(0,6)            then the next line
COBW012  LA    8,1(0,6)
         CR    8,7                 already at the line before the targe
         BNL   COBW020
         PUT   (2),(11)            skip a line
         LA    6,1(0,6)
         B     COBW012
COBW020  PUT   (2),(5)
         ST    7,0(0,3)            the paper is at the line just printe
         ST    7,0(0,10)           and so is LINE-COUNTER
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
RWONE    DC    H'1'
RTBLNK   DC    CL133' '            a blank line, ASA single space
RTSAVE3  DS    18F
RTOPEN   DC    X'00'
RTMAX    DC    H'120'
RTLINE   DC    CL121' '            ASA byte + 120 columns
RTSAVE1  DS    18F
RTSAVE2  DS    18F
RTSAVE5  DS    18F
RTSAVE6  DS    18F
RTUPSI   DS    F
UPSITAG  DC    C'UPSI'
UPSIMIN  DC    H'12'               UPSI, a bracket, eight digits
ACCOPEN  DC    X'00'
ACCEOFF  DC    X'00'
ACCBUF   DC    CL256' '            one card from SYSIN, blank padded
ACCMAX   DC    H'256'
ACCDCB   DCB   DDNAME=SYSIN,DSORG=PS,MACRF=(GM),                       X
               EODAD=0
RTDCB    DCB   DDNAME=SYSOUT,DSORG=PS,MACRF=(PM),RECFM=FBA,            X
               LRECL=121,BLKSIZE=121
*
* COBSTR -- STRING. R1 -> AL4(receiver), AL2(len), AL2(n),
*   AL4(pointer cell or 0); then per item AL4(addr), AL2(len),
*   AL2(delimiter len, 0 for SIZE), AL4(delimiter addr).
* Each item goes byte by byte until its delimiter matches or
* it runs out; the receiver filling up is the overflow, and
* a pointer outside 1..len is overflow with nothing moved.
* R15 = 0 done, 1 overflow. Other bytes of the receiver are
* not touched, which is the rule: STRING does not space-fill.
COBSTR   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE8+4
         LA    11,RTSAVE8
         ST    11,8(13)
         LR    13,11
         LR    2,1                 the block
         L     3,0(2)              receiver
         LH    5,4(2)              its length
         LH    7,6(2)              items
         L     4,8(2)              pointer cell
         LTR   4,4
         BZ    STR010              none: start at 1
         L     4,0(4)
         B     STR020
STR010   LA    4,1
STR020   BCTR  4,0                 position, from 0
         LTR   4,4
         BM    STRBAD              pointer below 1
         CR    4,5
         BNL   STRBAD              pointer past the end
         LA    6,12(2)             the first item
STR100   LTR   7,7
         BZ    STRDONE             all items sent
         L     8,0(6)              item
         LH    9,4(6)              its length
         LH    11,6(6)             delimiter length
         L     10,8(6)             delimiter
STR110   LTR   9,9
         BZ    STR190              item exhausted
         LTR   11,11
         BZ    STR120              SIZE: no delimiter to look for
         CR    9,11
         BL    STR120              too few left to hold the delimiter
         LR    15,11
         BCTR  15,0
         EX    15,STRCLC           delimiter here?
         BE    STR190              yes: the item ends
STR120   CR    4,5
         BNL   STROVF              receiver full
         LA    15,0(3,4)
         MVC   0(1,15),0(8)        one byte
         LA    8,1(8)
         BCTR  9,0
         LA    4,1(4)
         B     STR110
STR190   LA    6,12(6)             next item
         BCTR  7,0
         B     STR100
STRDONE  SR    15,15
         B     STRRET
STROVF   LA    15,1                overflow
STRRET   L     14,8(2)             pointer cell
         LTR   14,14
         BZ    STRX
         LA    4,1(4)              back to counting from 1
         ST    4,0(14)
         B     STRX
STRBAD   LA    15,1                pointer out of range: overflow, noth
STRX     L     13,4(13)
         ST    15,16(13)           R15 survives the LM through its own
         LM    14,12,12(13)
         BR    14
STRCLC   CLC   0(0,8),0(10)        executed with the delimiter length
RTSAVE8  DS    18F
*
* COBUNS -- UNSTRING. R1 -> AL4(sender), AL2(len), AL2(nd),
*   AL4(pointer cell or 0), AL4(tally cell or 0), AL2(nr),
*   AL2(0), AL4(0); then nd delimiters AL4(addr), AL2(len),
*   AL2(ALL); then nr receivers AL4(addr), AL2(len),
*   AL2(DELIMITER IN len), AL4(DELIMITER IN or 0),
*   AL4(COUNT IN cell or 0).
* For each receiver the sender is scanned from the position
* for the first place any delimiter matches, delimiters tried
* in order; the bytes before it go to the receiver, left
* justified and space filled. No delimiters means a receiver
* takes its own length. Bytes left when the receivers are
* used up are the overflow. R15 = 0 done, 1 overflow.
COBUNS   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE9+4
         LA    11,RTSAVE9
         ST    11,8(13)
         LR    13,11
         LR    2,1                 the block
         L     3,0(2)              sender
         LH    5,4(2)              its length
         LH    10,6(2)             delimiters
         L     4,8(2)              pointer cell
         LTR   4,4
         BZ    UNS010
         L     4,0(4)
