         CR    7,6
         BNH   MVL010
         LR    7,6                 bytes to move: the shorter
MVL010   SR    5,7                 bytes to fill afterwards
MVL020   LTR   7,7
         BNP   MVL040              moved
         LR    8,7
         CH    8,MVL256
         BNH   MVL030
         LH    8,MVL256            a piece
MVL030   BCTR  8,0
         EX    8,MVLMVC
         LA    8,1(8)
         AR    2,8
         AR    3,8
         SR    7,8
         B     MVL020
MVL040   LTR   5,5
         BNP   MVLX                nothing to fill
         MVI   0(2),C' '
         BCTR  5,0
MVL050   LTR   5,5
         BNP   MVLX
         LR    8,5
         CH    8,MVL256
         BNH   MVL060
         LH    8,MVL256
MVL060   BCTR  8,0
         EX    8,MVLPAD            propagate the space
         LA    8,1(8)
         AR    2,8
         SR    5,8
         B     MVL050
MVLX     L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
MVLMVC   MVC   0(0,2),0(3)         executed
MVLPAD   MVC   1(0,2),0(2)         executed
MVL256   DC    H'256'
RTSAVE13 DS    18F
         END
